module "eks_foundation" {
  source = "../../modules/compositions/eks-foundation"
}

resource "aws_iam_role" "vector" {
  name = "platform-demo-vector"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRoleWithWebIdentity"
      Principal = { Federated = module.eks_foundation.oidc_provider_arn }
    }]
  })
}
